-- ============================================================================
-- Azshara Crater - Quest POIs regenerated as AREAS (rectangles) from live spawns
-- Date: 2026-07-14
-- Each objective becomes a map area computed from the objective creature's spawn
-- bounding box (+/- pad) on map 37; turn-in POI is a small area at the turn-in NPC.
-- INSERT...SELECT is guarded on the creature existing on map 37, so absent-creature
-- objectives produce no misleading marker (see audit report in the chat).
-- ============================================================================

DELETE FROM `quest_poi` WHERE `QuestID` BETWEEN 300100 AND 300966;
DELETE FROM `quest_poi_points` WHERE `QuestID` BETWEEN 300100 AND 300966;

